%[text] # Motor Drive Unit - Simulation Case
%[text] ## Randomly generated input signals
%[text] Test that the model runs with reasonably random inputs. This is part of stress-test.
model_name = "HarnessModel_MotorDriveUnit";
load_system(model_name)

HarnessSetup_MotorDriveUnit

set_param(model_name + "/Motor Drive Unit", ReferencedSubsystem = "MotorDriveUnit_SystemTable_refsub")

set_param(model_name + "/Inputs", ReferencedSubsystem = "Inputs_MotorDriveUnit_Random_refsub")

% Initial conditions
initial.LoadInertiaSpeed = simscape.Value(0, "rpm");
initial.motorDriveUnit_RotorSpd_rpm = 0;
initial.ambientTemp_K = motorDriveUnit.ambientTemp_K;

sim_in = Simulink.SimulationInput(model_name);
sim_in = setModelParameter(sim_in, StopTime = "400");
%[text] Run simulation.
sim_out = sim(sim_in);
%[text] Visually inspect the result.
sim_data = extractTimetable(sim_out.logsout);

% Signal logging names in the model.
signal_names = [
  "Motor torque command"
  "Axle torque input"
  "Motor power rate"
  "Motor speed"
  "Motor temperature"
  "Battery power"
  "Battery current"
  "Battery voltage"
  ];

for idx = 1 : numel(signal_names) %[output:group:055667b6]
  fig = bev1mus.SignalUtil.plotTimedData(TimedData = sim_data, SignalName = signal_names(idx)); %[output:35a67d1c] %[output:0e727a62] %[output:27f5f37e] %[output:61477031] %[output:1cf8af9f] %[output:8d25e39e] %[output:067cafc0] %[output:38264e34]
  fig.Position(4) = 200;  % height
end %[output:group:055667b6]
